CREATE TABLE refunds ( id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), order_item_id TEXT NOT NULL REFERENCES order_items(id), user_id TEXT NOT NULL REFERENCES users(id), amount INTEGER NOT NULL CHECK (amount > 0), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','processed','rejected')), requested_by TEXT REFERENCES users(id), reviewed_by TEXT REFERENCES users(id), review_note TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), processed_at TEXT );
CREATE UNIQUE INDEX idx_refund_item_open ON refunds(order_item_id) WHERE status IN ('requested','processed');
CREATE INDEX idx_refund_status ON refunds(status, created_at);
CREATE TABLE provider_order_logs ( id TEXT PRIMARY KEY, order_item_id TEXT NOT NULL REFERENCES order_items(id) ON DELETE CASCADE, provider_id TEXT REFERENCES provider_integrations(id), attempt INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL, request_summary TEXT, response_summary TEXT, error TEXT, next_retry_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_pol_item ON provider_order_logs(order_item_id);
CREATE INDEX idx_pol_retry ON provider_order_logs(status, next_retry_at);
CREATE TABLE guards (id INTEGER PRIMARY KEY AUTOINCREMENT, ok INTEGER NOT NULL CHECK (ok = 1), label TEXT);
CREATE TABLE support_tickets ( id TEXT PRIMARY KEY, ticket_no TEXT NOT NULL UNIQUE, user_id TEXT NOT NULL REFERENCES users(id), subject TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'general', priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','urgent')), status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','waiting_customer','resolved','closed')), order_id TEXT REFERENCES orders(id), assigned_to TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_tk_user ON support_tickets(user_id, updated_at);
CREATE INDEX idx_tk_status ON support_tickets(status, updated_at);
CREATE TABLE support_messages ( id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, author_id TEXT NOT NULL REFERENCES users(id), is_staff INTEGER NOT NULL DEFAULT 0, is_internal INTEGER NOT NULL DEFAULT 0, body TEXT NOT NULL, attachment_key TEXT, attachment_name TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_sm_ticket ON support_messages(ticket_id, created_at);
CREATE TABLE notifications ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', link TEXT, read_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_nf_user ON notifications(user_id, read_at, created_at);
CREATE TABLE email_outbox ( id TEXT PRIMARY KEY, to_email TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','failed','skipped')), error TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE site_settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE cms_pages ( slug TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1 CHECK (published IN (0,1)), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE faqs ( id TEXT PRIMARY KEY, question TEXT NOT NULL, answer TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE admin_audit_logs ( id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, details TEXT NOT NULL DEFAULT '{}', ip TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_audit_time ON admin_audit_logs(created_at);
CREATE INDEX idx_audit_actor ON admin_audit_logs(actor_id, created_at);
